--
-- Table structure for table `TEACHING_ASSIGNMENT`
--

DROP TABLE IF EXISTS `TEACHING_ASSIGNMENT`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `TEACHING_ASSIGNMENT` (
  `assignment_id` int(11) NOT NULL AUTO_INCREMENT,
  `lecturer_id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `class_id` int(11) NOT NULL,
  `semester_id` int(11) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `assignment_status` varchar(30) NOT NULL,
  PRIMARY KEY (`assignment_id`),
  KEY `fk_assignment_lecturer` (`lecturer_id`),
  KEY `fk_assignment_course` (`course_id`),
  KEY `fk_assignment_class` (`class_id`),
  KEY `fk_assignment_semester` (`semester_id`),
  CONSTRAINT `fk_assignment_class` FOREIGN KEY (`class_id`) REFERENCES `CLASS` (`class_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_assignment_course` FOREIGN KEY (`course_id`) REFERENCES `COURSE` (`course_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_assignment_lecturer` FOREIGN KEY (`lecturer_id`) REFERENCES `LECTURER` (`lecturer_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_assignment_semester` FOREIGN KEY (`semester_id`) REFERENCES `SEMESTER` (`semester_id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_assignment_dates` CHECK (`end_date` is null or `start_date` < `end_date`)
) ENGINE=InnoDB AUTO_INCREMENT=3829 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

